// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GroupBuyRound) predicate.GroupBuyRound {
	return predicate.GroupBuyRound(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GroupBuyRound) predicate.GroupBuyRound {
	return predicate.GroupBuyRound(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GroupBuyRound) predicate.GroupBuyRound {
	return predicate.GroupBuyRound(sql.NotPredicates(p))
}
